arguments.command:
sqlite3 data/logs.sqlite '.schema' && sqlite3 -header data/logs.sqlite "
select stream, device, ab_arm, count(*), count(distinct session_id), min(served_at), max(served_at), sum(propensity=1.0) from rec_serves group by 1,2,3;
select count(*), count(distinct serve_id) from rec_candidates;
select r.stream, count(distinct r.serve_id), count(distinct c.serve_id) from rec_serves r left join rec_candidates c using(serve_id) group by 1;
select * from rec_serves limit 5;
select count(*) from click_events; select count(*), count(distinct serve_id||'-'||position) from click_events;
"

